-- =============================================================================
-- EnterprateAI — COMBINED local Supabase setup
-- Auto-generated by concatenating supabase_schema.sql + every migrations/*.sql
-- in dependency order, so a brand-new project can be set up in one run.
--
-- RUN THIS ONLY AGAINST A NEW, EMPTY, LOCAL-DEV SUPABASE PROJECT.
-- Do NOT run against the demo or live projects — every statement here is
-- idempotent (IF NOT EXISTS / ON CONFLICT) so it is safe there too, but it
-- is meant for bootstrapping local dev only.
-- =============================================================================

-- ─────────────────────────────────────────────────────────────────────────
-- SOURCE: supabase_schema.sql
-- ─────────────────────────────────────────────────────────────────────────
-- Supabase schema for EnterprateAI (Postgres)

create table if not exists users (
  id text primary key,
  email text unique not null,
  password_hash text,
  auth_provider text,
  google_sub text,
  name text,
  picture text,
  phone text,
  company text,
  email_verified boolean not null default false,
  email_verification_token text,
  is_blocked boolean not null default false,
  reset_token text,
  reset_token_expires_at timestamptz,
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);

create table if not exists workspaces (
  id text primary key,
  user_id text references users(id) on delete cascade,
  name text,
  data jsonb,
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);

-- Atomic top-level merge into workspaces.data — see supabase_schema.sql for the
-- full explanation. Replaces the app-level read-modify-write in
-- update_workspace(), which raced when two PATCH requests landed close together
-- (e.g. Catalogue "add customer" vs Financials "save invoice") and let whichever
-- committed second silently overwrite the other's change to an unrelated key.
create or replace function merge_workspace_data(
  p_workspace_id text,
  p_user_id text,
  p_patch jsonb,
  p_name text default null
) returns workspaces
language plpgsql
as $$
declare
  result workspaces;
begin
  update workspaces
  set
    data = coalesce(data, '{}'::jsonb)
      || (p_patch - 'financials')
      || case
           when p_patch ? 'financials' then
             jsonb_build_object(
               'financials',
               coalesce(data->'financials', '{}'::jsonb) || (p_patch->'financials')
             )
           else '{}'::jsonb
         end,
    name = coalesce(nullif(trim(p_name), ''), name),
    updated_at = now()
  where id = p_workspace_id and user_id = p_user_id
  returning * into result;

  return result;
end;
$$;

-- Reconstructed: referenced throughout the backend (credits, plans, auth,
-- integrations, idea_validation) but was never captured in a migration file —
-- it was created ad hoc in the Supabase dashboard on the existing projects.
-- Included here so a fresh project has it too.
create table if not exists user_subscriptions (
  id uuid primary key default gen_random_uuid(),
  user_id text not null unique references users(id) on delete cascade,
  plan_key text not null default 'explorer',
  billing_period text not null default 'monthly',
  status text not null default 'trial',
  stripe_subscription_id text,
  stripe_customer_id text,
  current_period_start timestamptz,
  current_period_end timestamptz,
  trial_started_at timestamptz,
  cancel_at_period_end boolean not null default false,
  cancelled_at timestamptz,
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);

create index if not exists user_subscriptions_user_idx on user_subscriptions(user_id);
create index if not exists user_subscriptions_stripe_sub_idx on user_subscriptions(stripe_subscription_id);
create index if not exists user_subscriptions_stripe_cust_idx on user_subscriptions(stripe_customer_id);

