  threshold_minor  integer      NOT NULL DEFAULT 5000,      -- £50 = 5000 pence
  hold_days        integer      NOT NULL DEFAULT 30,
  attribution_days integer      NOT NULL DEFAULT 30,
  recurring        boolean      NOT NULL DEFAULT true,
